package com.example.starter.domain;

/**
 * 掺烧方案流转状态：申报→审核→执行→（停止/禁烧）→日结封存。
 */
public enum PlanStatus {

    /** 已申报，待审核 */
    DECLARED,
    /** 审核通过，待下发执行 */
    APPROVED,
    /** 执行中：同一窑口同一时刻仅允许一个此状态方案 */
    EXECUTING,
    /** 已停止（方案切换先停旧） */
    STOPPED,
    /** 审核拒绝：替代率/氯硫/许可校验不通过，整单拒绝的终态 */
    REJECTED,
    /** 当日连续 3 个小时均值超标，强制禁烧 */
    BANNED,
    /** 日结封存，终态 */
    SEALED
}

package com.example.starter.domain;

/**
 * 降掺指令链状态：触发即下发（ISSUED）→执行确认（CONFIRMED）；
 * 下发后恰满 30 分钟未确认则自动升级（ESCALATED）并强制降掺至保底比例。
 */
public enum CommandStatus {

    /** 已触发并下发，等待执行确认 */
    ISSUED,
    /** 已在 30 分钟时限内执行确认 */
    CONFIRMED,
    /** 恰满/超过 30 分钟未确认，自动升级并强制降掺至保底比例 */
    ESCALATED
}

package com.example.starter.domain;

import java.math.BigDecimal;

/**
 * 参与小时均值评价的大气污染物（合成监测点口径），限值单位 mg/m3。
 */
public enum Pollutant {

    NOX(BigDecimal.valueOf(400)),
    SO2(BigDecimal.valueOf(200)),
    PARTICULATE(BigDecimal.valueOf(30));

    private final BigDecimal defaultLimitMgM3;

    Pollutant(BigDecimal defaultLimitMgM3) {
        this.defaultLimitMgM3 = defaultLimitMgM3;
    }

    /**
     * @return 配置缺省时的标准限值，单位 mg/m3
     */
    public BigDecimal defaultLimitMgM3() {
        return defaultLimitMgM3;
    }
}

package com.example.starter.config;

import java.time.Clock;
import java.time.ZoneId;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.EnableScheduling;

/**
 * 通用 Bean 配置：可控时钟（测试可替换为固定时钟）与定时调度（指令超时升级扫描）。
 */
@Configuration
@EnableScheduling
public class AppConfig {

    /** 业务统一使用 Asia/Shanghai 时区进行小时归位与日结切日。 */
    public static final ZoneId BUSINESS_ZONE = ZoneId.of("Asia/Shanghai");

    @Bean
    public Clock businessClock() {
        return Clock.system(BUSINESS_ZONE);
    }
}

package com.example.starter.config;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;
import org.springframework.boot.context.properties.ConfigurationProperties;

/**
 * 掺烧业务合成限值配置（cement.* 前缀）。
 *
 * @param chlorineLimitKgH      入窑氯总量限值，单位 kg/h
 * @param sulfurLimitKgH        入窑硫总量限值，单位 kg/h
 * @param maxHeatRatio          替代燃料热量替代率上限（含边界，恰 40% 合法）
 * @param reductionStep         单次降掺步长（热量替代率绝对降幅）
 * @param confirmDeadlineMinutes 降掺指令下发后的确认时限，单位分钟
 * @param consecutiveExceedanceBan 连续多少个小时均值超标触发当日禁烧
 * @param emissionLimits        各污染物小时均值标准限值，单位 mg/m3，恰等于限值判达标
 */
@ConfigurationProperties(prefix = "cement")
public record CementProperties(
        BigDecimal chlorineLimitKgH,
        BigDecimal sulfurLimitKgH,
        BigDecimal maxHeatRatio,
        BigDecimal reductionStep,
        long confirmDeadlineMinutes,
        int consecutiveExceedanceBan,
        Map<String, BigDecimal> emissionLimits) {

    public CementProperties {
        if (chlorineLimitKgH == null) {
            chlorineLimitKgH = new BigDecimal("0.6000");
        }
        if (sulfurLimitKgH == null) {
            sulfurLimitKgH = new BigDecimal("12.0000");
        }
        if (maxHeatRatio == null) {
            maxHeatRatio = new BigDecimal("0.4000");
        }
        if (reductionStep == null) {
            reductionStep = new BigDecimal("0.1000");
        }
        if (confirmDeadlineMinutes == 0L) {
            confirmDeadlineMinutes = 30L;
        }
        if (consecutiveExceedanceBan == 0) {
            consecutiveExceedanceBan = 3;
        }
        if (emissionLimits == null) {
            emissionLimits = new LinkedHashMap<>();
        }
    }
}

package com.example.starter.core;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态码与机器可读错误码，由统一异常处理层转换为响应体。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus status() {
        return status;
    }

    public String code() {
        return code;
    }

    /** 409 冲突，典型场景：同键异参、窑口被占用、状态不允许流转。 */
    public static ApiException conflict(String code, String message) {
        return new ApiException(HttpStatus.CONFLICT, code, message);
    }

    /** 422 业务拒绝，典型场景：审核校验失败导致整单拒绝。 */
    public static ApiException rejected(String code, String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, code, message);
    }

    /** 404 资源不存在。 */
    public static ApiException notFound(String code, String message) {
        return new ApiException(HttpStatus.NOT_FOUND, code, message);
    }
}

