package com.example.starter.api.dto;

import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import java.math.BigDecimal;
import java.util.List;

/**
 * 掺烧方案申报请求。
 *
 * @param requestId       申报幂等键，指纹覆盖该键与全部业务字段
 * @param kilnId          窑口编码，同一窑口同一时刻仅允许一个执行中方案
 * @param licenseNo       绑定的危废经营许可证编号（合成许可库）
 * @param declaredHeatRatio 申报的替代燃料热量替代率，上限 0.4（恰 0.4 合法）
 * @param floorHeatRatio  降掺保底比例，超时升级时强制降至此值
 * @param fuels           入窑燃料组分（含常规燃料与替代燃料），按投料量加权计算氯硫
 */
public record DeclarePlanRequest(
        @NotBlank String requestId,
        @NotBlank String kilnId,
        @NotBlank String licenseNo,
        @NotNull @DecimalMin("0.0000") @DecimalMax("1.0000") BigDecimal declaredHeatRatio,
        @NotNull @DecimalMin("0.0000") @DecimalMax("1.0000") BigDecimal floorHeatRatio,
        @NotEmpty List<FuelComponentRequest> fuels) {
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.math.BigDecimal;

/**
 * 入窑燃料组分项。
 *
 * @param fuelName          燃料名称（合成数据）
 * @param alternative       是否为替代燃料
 * @param feedRateKgH       入窑投料量，单位 kg/h
 * @param heatValueKcalKg   低位热值，单位 kcal/kg
 * @param chlorineContentPct 氯质量分数，单位 %（如 0.05 表示 0.05%）
 * @param sulfurContentPct  硫质量分数，单位 %
 */
public record FuelComponentRequest(
        @NotBlank String fuelName,
        @NotNull Boolean alternative,
        @NotNull @DecimalMin("0.0000") BigDecimal feedRateKgH,
        @NotNull @DecimalMin("0.0000") BigDecimal heatValueKcalKg,
        @NotNull @DecimalMin("0.0000") BigDecimal chlorineContentPct,
        @NotNull @DecimalMin("0.0000") BigDecimal sulfurContentPct) {
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.time.LocalDate;
import java.math.BigDecimal;

/**
 * 合成危废经营许可录入请求（仅用于本地合成许可库维护）。
 *
 * @param licenseNo  许可证编号
 * @param holderName  持证单位
 * @param validFrom   生效日期（含当日）
 * @param validTo     截止日期（含当日），申报审核时刻晚于该日期即过期拒绝
 * @param revoked     是否被吊销
 */
public record LicenseUpsertRequest(
        @NotBlank String licenseNo,
        @NotBlank String holderName,
        @NotNull LocalDate validFrom,
        @NotNull LocalDate validTo,
        Boolean revoked) {
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.time.LocalDateTime;
import java.math.BigDecimal;

/**
 * 排放读数上报项；按“测点＋采样时刻”去重，乱序上报按采样时刻归位。
 *
 * @param pointCode 测点编码
 * @param pollutant  污染物（NOX/SO2/PARTICULATE）
 * @param sampledAt  采样时刻
 * @param valueMgM3  监测值，单位 mg/m3
 */
public record ReadingItem(
        @NotBlank String pointCode,
        @NotBlank String pollutant,
        @NotNull LocalDateTime sampledAt,
        @NotNull BigDecimal valueMgM3) {
}

package com.example.starter.api.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotEmpty;
import java.util.List;

/**
 * 排放读数批量上报请求。
 */
public record ReadingBatchRequest(
        @NotEmpty @Valid List<ReadingItem> readings) {
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.NotNull;
import java.time.LocalDateTime;

/**
 * 小时评估请求：评估指定方案某一自然小时（Asia/Shanghai）的各污染物均值。
 *
 * @param hourStart 目标自然小时起点（分钟秒必须为 00:00）
 */
public record EvaluateHourRequest(
        @NotNull LocalDateTime hourStart) {
}

package com.example.starter.api.dto;

