                PlanStatus.EXECUTING.name(), Timestamp.valueOf(now), planId);
        return get(planId);
    }

    @Override
    public PlanResponse get(Long planId) {
        List<PlanResponse> plans = jdbcTemplate.query(
                "SELECT * FROM co_firing_plan WHERE id = ?", PlanRowMapper.INSTANCE, planId);
